module watchdog_timer (  
    input wire clk,  
    input wire reset,  
    input wire start,  
    output reg timeout  
);  
    parameter TIMEOUT_PERIOD = 5; // Timeout period in clock cycles  
    reg [2:0] count; // 3-bit counter for timeout period  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            timeout <= 0;  
        end else if (start) begin  
            count <= 0;  
            timeout <= 0;  
        end else if (count < TIMEOUT_PERIOD) begin  
            count <= count + 1;  
        end else begin  
            timeout <= 1;  
        end  
    end  
endmodule

