module fir_filter (  
    input [7:0] data_in,  
    input clk,  
    output reg [7:0] data_out  
);  
    reg [7:0] shift_reg [0:7];  
    integer i;  

    always @(posedge clk) begin  
        // Shift the input data through the shift register  
        for (i = 7; i > 0; i = i - 1)  
            shift_reg[i] <= shift_reg[i - 1];  
        shift_reg[0] <= data_in;  
    end  

    always @(*) begin  
        // Calculate the output as the sum of the tap inputs  
        data_out = 0;  
        for (i = 0; i < 8; i = i + 1)  
            data_out = data_out + shift_reg[i];  
    end  
endmodule

