module ofdm_transmitter(  
    input clk,  
    input reset,  
    input [3:0] data_in,  
    output reg [15:0] ofdm_out  
);  
    reg [1:0] modulated_data;  
    reg [15:0] ifft_output;  
    reg [15:0] cyclic_prefix;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            ofdm_out <= 0;  
        end else begin  
            // QPSK Modulation  
            case (data_in)  
                4'b0000: modulated_data <= 2'b00;  
                4'b0001: modulated_data <= 2'b01;  
                4'b0010: modulated_data <= 2'b10;  
                4'b0011: modulated_data <= 2'b11;  
                default: modulated_data <= 2'b00;  
            endcase  
            // IFFT (Simplified for this example)  
            ifft_output <= {modulated_data, 14'b0};  
            // Adding cyclic prefix  
            cyclic_prefix <= ifft_output[15:0];  
            ofdm_out <= {cyclic_prefix, ifft_output[15:0]};  
        end  
    end  
endmodule

