module ARQ_system (
    input clk,
    input rst,
    input [7:0] data_in,
    input error_detected,
    output reg [7:0] data_out,
    output reg send,
    output reg ack
);

    reg [1:0] state;
    parameter IDLE = 2'b00, SEND = 2'b01, WAIT_ACK = 2'b10, RESEND = 2'b11;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            data_out <= 8'b0;
            send <= 1'b0;
            ack <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    state <= SEND;
                end
                SEND: begin
                    data_out <= data_in;
                    send <= 1'b1;
                    state <= WAIT_ACK;
                end
                WAIT_ACK: begin
                    if (error_detected) begin
                        state <= RESEND;
                    end else begin
                        ack <= 1'b1; // Acknowledge the received packet
                        state <= IDLE;
                    end
                    send <= 1'b0;
                end
                RESEND: begin
                    state <= SEND; // Go back to sending data
                end
            endcase
        end
    end
endmodule

