module Timer16bit (  
    input clk,  
    input reset,  
    input enable,  
    output reg [15:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 16'b0;  
        end else if (enable) begin  
            if (count == 16'hFFFF)  
                count <= 16'b0;  
            else  
                count <= count + 1;  
        end  
    end  
endmodule

