module i2c_master (
    input wire clk,
    input wire rst,
    input wire start,
    input wire stop,
    input wire [7:0] data_in,
    output reg sda,
    output reg scl,
    output reg ack,
    output reg [7:0] data_out
);
    reg [3:0] state;
    reg [3:0] bit_cnt;

    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter TRANSMIT = 4'b0010;
    parameter ACK = 4'b0011;
    parameter STOP = 4'b0100;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            sda <= 1;
            scl <= 1;
            ack <= 0;
            data_out <= 8'b0;
            bit_cnt <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        sda <= 0; // Start condition
                        state <= START;
                    end
                end
                START: begin
                    scl <= 0; // Prepare for transmission
                    state <= TRANSMIT;
                    bit_cnt <= 0;
                    data_out <= data_in;
                end
                TRANSMIT: begin
                    sda <= data_out[7 - bit_cnt]; // Send data bit
                    scl <= 1; // Clock high
                    state <= ACK;
                end
                ACK: begin
                    scl <= 0; // Clock low
                    if (bit_cnt < 7) begin
                        bit_cnt <= bit_cnt + 1; // Move to next bit
                        state <= TRANSMIT;
                    end else begin
                        ack <= 1; // Acknowledge received
                        state <= STOP; // Move to stop
                    end
                end
                STOP: begin
                    sda <= 1; // Stop condition
                    state <= IDLE; // Go back to idle
                end
            endcase
        end
    end
endmodule

