module deserializer (
    input wire clk,
    input wire rst,
    input wire serial_in,
    output reg [31:0] parallel_out
);
    reg [4:0] bit_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            parallel_out <= 32'b0;
            bit_count <= 5'b0;
        end else if (bit_count < 32) begin
            parallel_out <= {serial_in, parallel_out[31:1]};
            bit_count <= bit_count + 1;
        end
    end
endmodule

