module divider_4bit (
    input [3:0] dividend,
    input [3:0] divisor,
    input start,
    input clk,
    input reset,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg done
);
    reg [3:0] temp_dividend;
    reg [3:0] temp_quotient;
    reg [2:0] count; // 3 bits to count down from 4

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            quotient <= 4'b0000;
            remainder <= 4'b0000;
            temp_dividend <= 4'b0000;
            temp_quotient <= 4'b0000;
            count <= 3'b000;
            done <= 1'b0;
        end else if (start) begin
            if (count < 4) begin
                temp_dividend = {remainder[2:0], dividend[3-count]};
                if (temp_dividend >= divisor) begin
                    temp_dividend = temp_dividend - divisor;
                    temp_quotient[count] = 1'b1;
                end else begin
                    temp_quotient[count] = 1'b0;
                end
                remainder <= temp_dividend;
                quotient <= temp_quotient;
                count <= count + 1;
            end else begin
                done <= 1'b1;
            end
        end
    end
endmodule

