module lzw_compression (  
    input clk,  
    input rst,  
    input [7:0] char_in,  
    input valid_in,  
    output reg [15:0] code_out,  
    output reg valid_out  
);  
    parameter DICTIONARY_SIZE = 256;  
    reg [7:0] dictionary [0:DICTIONARY_SIZE-1];  
    reg [7:0] current_string [0:DICTIONARY_SIZE-1];  
    integer index;  
    integer current_length;  
    integer next_index;  

    initial begin  
        // Initialize the dictionary with single characters  
        for (index = 0; index < DICTIONARY_SIZE; index = index + 1)  
            dictionary[index] = index;  
        current_length = 0;  
        next_index = DICTIONARY_SIZE;  
    end  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            current_length <= 0;  
            valid_out <= 0;  
        end else if (valid_in) begin  
            // Add character to current string  
            current_string[current_length] = char_in;  
            current_length = current_length + 1;  

            // Check if the current string exists in the dictionary  
            // For simplicity, we will just look for the last character  
            code_out = char_in;  
            valid_out = 1;  

            // Placeholder for adding new entries to the dictionary  
            if (next_index < DICTIONARY_SIZE) begin  
                dictionary[next_index] = char_in;  
                next_index = next_index + 1;  
            end  
        end  
    end  
endmodule

