    wire [7:0] data_out;
    wire data_ready;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    uart_receiver dut (
        .clk(clk),
        .reset(reset),
        .rx(rx),
        .data_out(data_out),
        .data_ready(data_ready)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        reset = 1;
        rx = 1;
        #20;
        reset = 0;
        #20;
    end
        endtask
    task send_uart_byte;

        input [7:0] byte_to_send;
        integer i;
        begin

            rx = 0;
            #BIT_PERIOD;


            for (i = 0; i < 8; i = i + 1) begin
                rx = byte_to_send[i];
                #BIT_PERIOD;
            end


            rx = 1;
            #BIT_PERIOD;


            #(BIT_PERIOD/2);
        end
        endtask

    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Test Case %0d: Receive 0xA5 (10100101)", test_num);
