module watchdog_timer(  
    input clk,  
    input reset,  
    input kick,  
    output reg wdt_reset  
);  
    parameter TIMEOUT = 8'd100;  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            wdt_reset <= 0;  
        end else begin  
            if (kick) begin  
                counter <= 0;  
                wdt_reset <= 0;  
            end else begin  
                if (counter >= TIMEOUT) begin  
                    wdt_reset <= 1;  
                end else begin  
                    counter <= counter + 1;  
                end  
            end  
        end  
    end  
endmodule

