module watchdog_timer (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [3:0] timeout_count,
    output reg timeout_event
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            timeout_event <= 0;
        end else if (enable) begin
            if (counter < timeout_count) begin
                counter <= counter + 1;
                timeout_event <= 0;
            end else begin
                timeout_event <= 1; // Timeout event triggered
            end
        end
    end
endmodule

