module deserializer_16bit (  
    input clk,  
    input reset,  
    input serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            parallel_out <= 16'b0;  
            count <= 4'b0;  
        end else begin  
            if (count < 16) begin  
                parallel_out <= {parallel_out[14:0], serial_in};  
                count <= count + 1;  
            end  
        end  
    end  
endmodule

