module state_machine (
    input clk,
    input reset,
    input start,
    input done,
    output reg [1:0] state_out
);
    // State encoding
    parameter IDLE = 2'b00, WORKING = 2'b01, DONE = 2'b10;
    reg [1:0] current_state, next_state;

    // State transition
    always @(posedge clk or posedge reset) begin
        if (reset) 
            current_state <= IDLE;
        else 
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: 
                if (start) next_state = WORKING;
                else next_state = IDLE;
            WORKING: 
                if (done) next_state = DONE;
                else next_state = WORKING;
            DONE: 
                next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Output logic
    always @(posedge clk) begin
        state_out <= current_state;
    end
endmodule

module shift_register (
    input clk,
    input reset,
    input [1:0] d,
    output reg [1:0] q
);
    always @(posedge clk or posedge reset) begin
        if (reset)
            q <= 2'b00;
        else
            q <= {q[0], d}; // Shift left and insert d at LSB
    end
endmodule

module sliding_window_protocol(  
    input clk,  
    input rst,  
    input send_frame,  
    input ack_received,  
    output reg [3:0] frame_sent,  
    output reg [3:0] frame_acknowledged  
);  
    reg [1:0] state;  
    parameter IDLE = 2'b00, SENDING = 2'b01, WAITING_ACK = 2'b10;  
    parameter WINDOW_SIZE = 4;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            frame_sent <= 4'b0000;  
            frame_acknowledged <= 4'b0000;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send_frame && (frame_sent < WINDOW_SIZE)) begin  
                        frame_sent <= frame_sent + 1;  
                        state <= SENDING;  
                    end  
                end  
                SENDING: begin  
                    state <= WAITING_ACK;  
                end  
                WAITING_ACK: begin  
                    if (ack_received) begin  
                        frame_acknowledged <= frame_acknowledged + 1;  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

