module pulse_generator (
    input clk,
    input rst,
    input [7:0] pulse_width,
    input [7:0] period,
    output reg pulse_out
);
    reg [7:0] count;
    reg [7:0] state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            state <= 0;
            pulse_out <= 0;
        end else begin
            if (state < period) begin
                if (count < pulse_width) begin
                    pulse_out <= 1;
                    count <= count + 1;
                end else begin
                    pulse_out <= 0;
                    count <= count + 1;
                end
            end
            if (state < period - 1) begin
                state <= state + 1;
            end else begin
                state <= 0;
                count <= 0;
            end
        end
    end
endmodule

