module SRT_Divider (
    input [15:0] numerator,
    input [15:0] denominator,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    input clk,
    input start,
    output reg done
);

    reg [15:0] A; // Accumulator
    reg [15:0] Q; // Quotient
    reg [15:0] M; // Divisor
    reg [4:0] count; // Counter for bits processed
    reg state; // State variable

    always @(posedge clk) begin
        if (start) begin
            A <= numerator;
            Q <= 0;
            M <= denominator;
            count <= 16;
            done <= 0;
            state <= 1;
        end else if (state) begin
            // SRT Division Algorithm
            // Simplified version for demonstration purposes
            if (A >= M) begin
                A <= A - M;
                Q <= Q + 1;
            end else begin
                // Select a digit to subtract (simplified)
                Q <= Q;
            end
            count <= count - 1;
            if (count == 0) begin
                remainder <= A;
                quotient <= Q;
                done <= 1;
                state <= 0;
            end
        end
    end
endmodule

module mpc_controller(  
    input wire clk,  
    input wire reset,  
    input wire [7:0] input_signal,  
    output reg [7:0] control_signal  
);  
    parameter PROPORTIONAL_GAIN = 8'd2;  
    parameter MAX_OUTPUT = 8'd255;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            control_signal <= 8'd0;  
        else  
            control_signal <= (input_signal * PROPORTIONAL_GAIN > MAX_OUTPUT) ? MAX_OUTPUT : (input_signal * PROPORTIONAL_GAIN);  
    end  
endmodule

