module phase_detector (
    input clk_A,
    input clk_B,
    output reg out_A_leads,
    output reg out_B_leads,
    output reg out_in_phase
);
    reg [1:0] count_A;
    reg [1:0] count_B;

    always @(posedge clk_A or posedge clk_B) begin
        if (clk_A) begin
            count_A <= count_A + 1;
        end
        if (clk_B) begin
            count_B <= count_B + 1;
        end

        if (count_A > count_B) begin
            out_A_leads = 1;
            out_B_leads = 0;
            out_in_phase = 0;
        end else if (count_A < count_B) begin
            out_A_leads = 0;
            out_B_leads = 1;
            out_in_phase = 0;
        end else begin
            out_A_leads = 0;
            out_B_leads = 0;
            out_in_phase = 1;
        end
    end
endmodule

module fft_butterfly (
    input wire clk,
    input wire rst,
    input wire valid_in,
    input wire signed [15:0] a_real,
    input wire signed [15:0] a_imag,
    input wire signed [15:0] b_real,
    input wire signed [15:0] b_imag,
    output reg signed [15:0] out_a_real,
    output reg signed [15:0] out_a_imag,
    output reg signed [15:0] out_b_real,
    output reg signed [15:0] out_b_imag,
    output reg valid_out
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out_a_real <= 0;
            out_a_imag <= 0;
            out_b_real <= 0;
            out_b_imag <= 0;
            valid_out <= 0;
        end else if (valid_in) begin
            // Butterfly operation: 
            // out_a = a + b
            // out_b = a - b
            out_a_real <= a_real + b_real;
            out_a_imag <= a_imag + b_imag;
            out_b_real <= a_real - b_real;
            out_b_imag <= a_imag - b_imag;
            valid_out <= 1;
        end else begin
            valid_out <= 0;
        end
    end
endmodule

